<script setup>
import InstallTelegram from './InstallTelegram.vue'
import NetworkSettings from './NetworkSettings.vue'
import WalletSettings from './WalletSettings.vue'
import { reactive,ref,onMounted,computed,watch } from 'vue'
import TouchKeyboard from './TouchKeyboard.vue'
import {api} from './api'
const language=ref(localStorage.getItem('sammoy-ui-language') || 'ru')
const tr=(ru,uz,en)=>({ru,uz,en}[language.value]||ru)
const theme=ref(localStorage.getItem('sammoy-ui-theme')==='dark'?'dark':'light')
function toggleTheme(){theme.value=theme.value==='light'?'dark':'light';document.documentElement.dataset.theme=theme.value;localStorage.setItem('sammoy-ui-theme',theme.value)}
document.documentElement.dataset.theme=theme.value
const networkDirty=ref(false),networkPending=ref(false)
const step=ref(1),walletDirty=ref(false),walletChoice=ref('later'),walletStatus=ref(null),telegramChoice=ref('later'),telegramBusy=ref(false)
const steps=computed(()=>[tr('Проверка','Tekshiruv','Checks'),tr('Активация','Faollashtirish','Activation'),tr('Кошелёк и роли','Hamyon va rollar','Wallet and roles'),'Telegram',tr('Запуск','Ishga tushirish','Launch')])
watch(language,value=>localStorage.setItem('sammoy-ui-language',value))
const activated=computed(()=>Boolean(status.value?.site?.site_code)&&!status.value?.license?.locked)
const ready=computed(()=>safeToInstall.value&&status.value?.hardware?.complete&&status.value?.io_ready&&activated.value)
async function refreshWallet(){walletStatus.value=await api('/api/commissioning/wallet')}
async function next(){
  await load()
  if(step.value===1){if(networkDirty.value||networkPending.value)throw Error(tr('Сохраните сеть и подтвердите подключение.','Tarmoqni saqlang va ulanishni tasdiqlang.','Save the network and confirm connectivity.'));if(!safeToInstall.value||!status.value.hardware.complete||!status.value.io_ready)throw Error(tr('Проверьте оборудование и завершите сеанс.','Uskunani tekshiring va seansni yakunlang.','Check hardware and finish the session.'));step.value=2}
  else if(step.value===2){if(!activated.value)throw Error(tr('Сначала активируйте пост и проверьте лицензию.','Avval postni faollashtiring va litsenziyani tekshiring.','Activate the station and check its license first.'));await refreshWallet();walletChoice.value=walletStatus.value.configuration.enabled?'shared':'later';step.value=3}
  else if(step.value===4){if(telegramBusy.value)return;step.value=5}
  else if(step.value===3){if(walletDirty.value)throw Error(tr('Сохраните изменения ролей.','Rollar o‘zgarishini saqlang.','Save role changes.'));await refreshWallet();if(walletChoice.value==='shared'&&!walletStatus.value.configuration.enabled)throw Error(tr('Сначала сохраните роли кошелька.','Avval hamyon rollarini saqlang.','Save wallet roles first.'));step.value=4}
}
async function resync(){await ensureIdle();await api('/api/commissioning/sync',{method:'POST',body:'{}'});await load()}
async function start(){const installed=await api('/api/commissioning/state');if(installed.complete){status.value={commissioning:{complete:true}};step.value=5;return}await load();step.value=status.value.commissioning.complete?5:activated.value?2:1}

const status=ref(null),error=ref(''),notice=ref(''),busy=ref(false),tab=ref('online'),confirm=ref(false),wash=ref(null)
const form=reactive({gateway_url:'',activation_code:'',site_code:'',post_no:1,purpose:'activate',click_enabled:false})
const safeToInstall=computed(()=>wash.value && !wash.value.activeMode && !wash.value.armedMode && !wash.value.requestedOutput && !wash.value.activeSessionId && Number(wash.value.creditSum)===0)
async function load(){status.value=await api('/api/commissioning/status');wash.value=(await api('/api/wash/state')).state;if(!form.gateway_url)form.gateway_url=status.value.site.gateway_url.includes('example.com')?'https://pay.labrix.uz':status.value.site.gateway_url;form.site_code ||= status.value.site.site_code;form.post_no=status.value.site.post_no || 1}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function ensureIdle(){wash.value=(await api('/api/wash/state')).state;if(!safeToInstall.value)throw Error(tr('Завершите сеанс мойки перед активацией поста.','Postni faollashtirishdan oldin yuvish seansini yakunlang.','Finish the wash session before station activation.'))}
async function claim(){await ensureIdle();status.value=await api('/api/commissioning/claim',{method:'POST',body:JSON.stringify({gateway_url:form.gateway_url,activation_code:form.activation_code,click_enabled:form.click_enabled})});form.activation_code='';notice.value=tr('Пост активирован. Проверьте данные и завершите установку.','Post faollashtirildi. Ma’lumotlarni tekshiring va sozlashni yakunlang.','Station activated. Check the details and finish setup.')}
async function download(){const {activation_code,...payload}=form;const data=await api('/api/commissioning/offline-request',{method:'POST',body:JSON.stringify(payload)});const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='sammoy-post-'+form.post_no+'.request.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importResponse(event){const file=event.target.files?.[0];if(!file)return;await run(async()=>{await ensureIdle();const data=new FormData();data.append('file',file);const r=await fetch('/api/commissioning/offline-response',{method:'POST',body:data,signal:AbortSignal.timeout(60000)});const body=await r.json();if(!r.ok)throw Error(body.detail || 'Import failed');status.value=body;notice.value=tr('Ответ импортирован','Javob import qilindi','Response imported')});event.target.value=''}
async function complete(){await ensureIdle();await load();if(!ready.value)throw Error(tr('Пост ещё не готов к запуску.','Post hali ishga tayyor emas.','The station is not ready yet.'));status.value=await api('/api/commissioning/complete',{method:'POST',body:JSON.stringify({confirmation:'READY'})});confirm.value=false;notice.value=tr('Установка завершена. Telegram можно настроить или изменить в Owner → Telegram на главном посте.','Sozlash yakunlandi. Telegramni asosiy postda Owner → Telegram orqali sozlash yoki o‘zgartirish mumkin.','Setup complete. Configure or update Telegram in Owner → Telegram on the primary station.')}
onMounted(()=>run(start))
</script>
<template><main class="shell"><header class="topbar"><div class="brand"><strong>Labrixwash</strong><span>{{ tr('Установка поста','Postni sozlash','Station setup') }}</span></div><div class="top-actions"><button class="quiet" @click="toggleTheme">{{ theme==='light'?'◐ Dark':'☀ Light' }}</button><div class="language"><button v-for="lang in ['ru','uz','en']" :class="{active:language===lang}" @click="language=lang">{{ lang.toUpperCase() }}</button></div><a class="quiet install-link" href="/login">{{ tr('Вход','Kirish','Sign in') }}</a></div></header>
<section class="owner-page install-wizard"><nav class="install-steps" :aria-label="tr('Этапы установки','Sozlash bosqichlari','Setup steps')"><div v-for="(title,index) in steps" :key="index" :class="{current:step===index+1,done:step>index+1}" :aria-current="step===index+1?'step':undefined"><span>{{index+1}}</span><strong>{{title}}</strong></div></nav><div class="heading"><h1>{{ tr('Настройка новой мойки','Yangi yuvishni sozlash','New wash setup') }}</h1><p>{{ tr('Установите каждый пост отдельно. Код мойки и общий ключ выдаёт сервер активации; номера постов должны различаться.','Har bir postni alohida sozlang. Yuvish kodi va umumiy kalit faollashtirish serveridan olinadi; post raqamlari turlicha bo‘lishi kerak.','Set up each station separately. The activation server supplies the site code and shared key; station numbers must be unique.') }}</p></div>
<div v-if="error" class="message error" role="alert">{{ error }}</div><div v-if="notice" class="message success" role="status">{{ notice }}</div><p v-if="busy" role="status">{{ tr('Загрузка…','Yuklanmoqda…','Loading…') }}</p>
<template v-if="status"><NetworkSettings v-if="step===1 && !status.commissioning.complete" api-base="/api/commissioning/network" :language="language" :idle="safeToInstall" @dirty="networkDirty=$event" @status="networkPending=Boolean($event?.pending)"/><div v-if="!status.commissioning.complete" class="metrics"><section class="card metric"><p>{{ tr('Контроллер','Kontroller','Controller') }}</p><strong>{{ status.hardware.complete?'OK':'—' }}</strong></section><section class="card metric"><p>Modbus I/O</p><strong>{{ status.io_ready?'OK':'—' }}</strong></section><section class="card metric"><p>{{ tr('Код мойки','Yuvish kodi','Site code') }}</p><strong>{{ status.site.site_code || '—' }}</strong></section><section class="card metric"><p>{{ tr('Пост','Post','Station') }}</p><strong>{{ status.site.post_no }}</strong></section></div>
<template v-if="!status.commissioning.complete"><div v-if="!safeToInstall" class="message error">{{ tr('На посте есть незавершённый сеанс. Активация доступна после его завершения.','Postda yakunlanmagan seans bor. Faollashtirish u yakunlangach mumkin.','A wash session is still open. Activation is available after it is finished.') }}<button class="quiet" :disabled="busy" @click="run(load)">{{ tr('Обновить','Yangilash','Refresh') }}</button></div>
<div v-if="step===2" class="actions" style="margin-bottom:24px"><button class="quiet" @click="tab='online'">{{ tr('По коду активации','Faollashtirish kodi','Activation code') }}</button><button class="quiet" @click="tab='offline'">{{ tr('Через файл','Fayl orqali','Via file') }}</button></div>
<form v-if="step===2 && tab==='online'" class="card content" @submit.prevent="run(claim)"><div class="fields"><label>{{ tr('Адрес сервера активации','Faollashtirish serveri manzili','Activation server address') }}<input v-model.trim="form.gateway_url" type="url" placeholder="https://…" required maxlength="300" /></label><label>{{ tr('Код активации поста','Postni faollashtirish kodi','Station activation code') }}<input v-model.trim="form.activation_code" minlength="8" maxlength="32" required autocomplete="off" /></label><label class="check"><input v-model="form.click_enabled" type="checkbox" />{{ tr('Включить Click','Clickni yoqish','Enable Click') }}</label><button class="primary" :disabled="busy || !safeToInstall || !status.hardware.complete || !status.io_ready">{{ tr('Активировать пост','Postni faollashtirish','Activate station') }}</button></div></form>
<form v-if="step===2 && tab==='offline'" class="card content" @submit.prevent="run(download)"><div class="fields"><label>{{ tr('Код мойки','Yuvish kodi','Site code') }}<input v-model.trim="form.site_code" maxlength="80" required /></label><label>{{ tr('Номер поста','Post raqami','Station number') }}<input v-model.number="form.post_no" type="number" min="1" max="1000" required /></label><label>{{ tr('Адрес сервера активации','Faollashtirish serveri manzili','Activation server address') }}<input v-model.trim="form.gateway_url" type="url" required maxlength="300" /></label><label>{{ tr('Назначение','Maqsad','Purpose') }}<select v-model="form.purpose"><option value="activate">{{ tr('Новый пост','Yangi post','New station') }}</option><option value="replace_microsd">{{ tr('Замена microSD','microSD almashtirish','Replace microSD') }}</option></select></label><div class="full"><p class="muted">{{ tr('Скачайте запрос, подтвердите его на сервере активации и загрузите подписанный файл ответа.','So‘rovni yuklab oling, faollashtirish serverida tasdiqlang va imzolangan javob faylini yuklang.','Download the request, approve it on the activation server, then upload the signed response.') }}</p><button class="quiet" :disabled="busy || !status.hardware.complete">{{ tr('Скачать запрос','So‘rovni yuklab olish','Download request') }}</button></div><label>{{ tr('Файл ответа','Javob fayli','Response file') }}<input type="file" accept="application/json,.json" :disabled="busy || !safeToInstall" @change="importResponse" /></label></div></form>
<section v-if="step===2 && status.site.site_code" class="card content"><h2>{{tr('Проверка лицензии','Litsenziyani tekshirish','License check')}}</h2><p>{{status.license.locked?status.license.reason:tr('Лицензия активна','Litsenziya faol','License active')}}</p><button class="quiet" :disabled="busy || !safeToInstall" @click="run(resync)">{{tr('Проверить активацию','Faollashtirishni tekshirish','Check activation')}}</button></section>
<section v-if="step===3" class="card content"><h2>{{steps[2]}}</h2><p>{{tr('На всех постах одной мойки укажите одинаковые номера главного и резервного. Переключение резерва выполняется вручную.','Bir yuvishdagi barcha postlarda asosiy va zaxira post raqamlari bir xil bo‘lsin. Zaxiraga o‘tish qo‘lda bajariladi.','Use the same primary and standby numbers on every station. Failover is manual.')}}</p><div class="actions"><button class="quiet" :class="{selected:walletChoice==='shared'}" :disabled="walletDirty" @click="walletChoice='shared'">{{tr('Настроить общий кошелёк','Umumiy hamyonni sozlash','Configure shared wallet')}}</button><button v-if="!walletStatus?.configuration?.enabled" class="quiet" :class="{selected:walletChoice==='later'}" :disabled="walletDirty" @click="walletChoice='later'">{{tr('Настроить позже','Keyinroq sozlash','Set up later')}}</button></div><p v-if="walletChoice==='later'" class="muted">{{tr('Карты пока работают только на этом посте. Общий кошелёк можно подключить позже с переносом остатков.','Kartalar hozircha faqat shu postda ishlaydi. Umumiy hamyonni keyin qoldiqlarni ko‘chirish bilan ulash mumkin.','Cards remain local to this station. Shared wallet can be configured later with balance migration.')}}</p><WalletSettings v-if="walletChoice==='shared'" install :language="language" @dirty="walletDirty=$event" @saved="refreshWallet"/></section>
<section v-if="step===4" class="card content"><h2>Telegram</h2><p>{{tr('Подключить отчёты и уведомления сейчас? Это необязательно: настройка останется доступна в Owner → Telegram.','Hisobot va bildirishnomalarni hozir ulaysizmi? Bu ixtiyoriy: keyin Owner → Telegram orqali sozlash mumkin.','Connect reports and notifications now? This is optional; you can set it up later in Owner → Telegram.')}}</p><div class="actions"><button class="quiet" :class="{selected:telegramChoice==='now'}" :disabled="telegramBusy" @click="telegramChoice='now'">{{tr('Подключить сейчас','Hozir ulash','Connect now')}}</button><button class="quiet" :class="{selected:telegramChoice==='later'}" :disabled="telegramBusy" @click="telegramChoice='later'">{{tr('Настроить позже в Owner','Keyin Owner orqali sozlash','Set up later in Owner')}}</button></div><InstallTelegram v-if="telegramChoice==='now'" :language="language" @busy="telegramBusy=$event"/></section><section v-if="step===5" class="card content"><h2>{{tr('Проверка перед запуском','Ishga tushirishdan oldingi tekshiruv','Pre-launch check')}}</h2><p>{{tr('Мойка','Yuvish','Site')}}: <strong>{{status.site.site_code}}</strong> · {{tr('Пост','Post','Station')}} <strong>{{status.site.post_no}}</strong></p><p>{{tr('Оборудование','Uskuna','Hardware')}}: {{status.hardware.complete&&status.io_ready?'OK':'—'}} · {{tr('Лицензия','Litsenziya','License')}}: {{activated?'OK':'—'}}</p><p>{{tr('Telegram необязателен для запуска мойки. Вернуться к настройке можно в Owner → Telegram на главном посте.','Telegram yuvishni ishga tushirish uchun majburiy emas. Sozlashni asosiy postda Owner → Telegram orqali davom ettirish mumkin.','Telegram is optional. Return to its settings in Owner → Telegram on the primary station.')}}</p><p>{{tr('Перед работой с клиентами смените начальные пароли Owner и Admin и выполните аппаратные проверки.','Mijozlarga xizmat ko‘rsatishdan oldin Owner va Admin boshlang‘ich parollarini o‘zgartiring va uskunani tekshiring.','Change initial Owner and Admin passwords and complete hardware checks before serving customers.')}}</p></section>
<div class="actions end install-navigation"><button v-if="step>1" class="quiet" :disabled="busy||walletDirty||telegramBusy" @click="step--">{{tr('Назад','Orqaga','Back')}}</button><button class="quiet" :disabled="busy" @click="run(load)">{{tr('Обновить','Yangilash','Refresh')}}</button><button v-if="step<5" class="primary" :disabled="busy||telegramBusy||!safeToInstall||walletDirty||(step===1&&(networkDirty||networkPending||!status.hardware.complete||!status.io_ready))||(step===2&&!activated)" @click="run(next)">{{step===4&&telegramChoice==='later'?tr('Пропустить и продолжить','O‘tkazib yuborish va davom etish','Skip and continue'):tr('Продолжить','Davom etish','Continue')}}</button><button v-else class="primary" :disabled="busy||!ready" @click="confirm=true">{{tr('Завершить установку','Sozlashni yakunlash','Finish setup')}}</button></div></template><p v-else class="message success">{{ tr('Установка этого поста завершена.','Ushbu postni sozlash yakunlangan.','This station setup is complete.') }}</p><a v-if="status.commissioning.complete" class="primary install-open" href="/wash">{{tr('Открыть мойку','Yuvish ekranini ochish','Open wash')}}</a></template></section>
<div v-if="confirm" class="confirm-backdrop"><section class="card confirm-dialog" role="alertdialog" aria-modal="true"><h2>{{ tr('Завершить установку поста','Post sozlamalarini yakunlash','Complete station setup') }} {{ status.site.post_no }}?</h2><p>{{ status.site.site_code }}</p><div class="actions"><button class="quiet" @click="confirm=false">{{ tr('Отмена','Bekor qilish','Cancel') }}</button><button class="primary" :disabled="busy" @click="run(complete)">{{ tr('Подтвердить','Tasdiqlash','Confirm') }}</button></div></section></div><TouchKeyboard :language="language" /></main></template>

<style scoped>.install-wizard{max-width:1100px;margin:0 auto}.install-steps{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:32px}.install-steps>div{padding:18px;border-bottom:3px solid var(--border);display:flex;align-items:center;gap:12px;color:var(--muted)}.install-steps .current{border-color:var(--accent,#1764d8);color:var(--text)}.install-steps .done{color:var(--text)}.install-steps span{font-size:24px}.install-navigation{margin-top:28px;gap:16px}.install-wizard .selected{outline:3px solid var(--accent,#1764d8)}.install-open{display:inline-block;padding:20px 28px;text-decoration:none}.install-wizard .content{margin:24px 0;padding:28px}.install-wizard .content p{line-height:1.6}@media(max-width:650px){.install-steps{grid-template-columns:repeat(2,1fr)}.install-steps>div{padding:12px;font-size:14px}.install-wizard .content{padding:20px}}.install-network{margin-bottom:24px}.install-network>summary{padding:24px;border:1px solid var(--border);border-radius:8px;cursor:pointer;font-size:22px;font-weight:700}</style>
